import heapq


def _ledger(revision_priority, tax_base):
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (numerator + denominator // 2) // denominator
        return numerator // denominator

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            if revision_priority == "sequence_first":
                key = (sequence, event.get("revision", 0), position)
            else:
                key = (event.get("revision", 0), position)
            if event_id not in chosen or key > chosen[event_id][0]:
                chosen[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            base = net if tax_base == "discounted" else raw
            tax = rounded(base * event.get("tax_bp", 0), 10000, mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _component_06():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        choices = []
        for name in names:
            forbidden = set(blocked.get(name, []))
            versions = [row["version"] for row in packages[name]
                        if row["version"] not in forbidden
                        and (name not in pins or row["version"] == pins[name])]
            choices.append([-1] + versions)

        best_vector = None
        best_install = None
        for values in product(*choices):
            assigned = dict(zip(names, values))
            installed = {name for name, version in assigned.items() if version != -1}
            edges = {name: [] for name in installed}
            closure = set()
            pending = list(data.get("roots", {}))
            valid = True

            while pending and valid:
                name = pending.pop()
                if name in closure:
                    continue
                closure.add(name)
                version = assigned.get(name, -1)
                if version == -1:
                    valid = False
                    break
                row = next((r for r in packages[name] if r["version"] == version), None)
                if row is None:
                    valid = False
                    break
                if name in data.get("roots", {}):
                    low, high = data["roots"][name]
                    if not low <= version <= high:
                        valid = False
                        break
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = dep["name"]
                    edges[name].append(target)
                    target_version = assigned.get(target, -1)
                    if target_version == -1 or not dep["min"] <= target_version <= dep["max"]:
                        valid = False
                        break
                    pending.append(target)

            if not valid or closure != installed:
                continue

            finished = set()
            active = set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not visit(target) for target in edges.get(name, [])):
                    return False
                active.remove(name)
                finished.add(name)
                return True

            if not all(visit(name) for name in installed):
                continue
            if any(name not in installed for name in data.get("roots", {})):
                continue
            if best_vector is None or values > best_vector:
                best_vector = values
                best_install = {name: assigned[name] for name in installed}

        if best_install is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_install}
    return solve


def _component_07():
    def solve(data):
        k = data["k"]
        blocked = set(data.get("blocked", []))
        jobs = [job for job in data["jobs"] if job["id"] not in blocked]
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_ids = None
        best_value = None

        if k > len(jobs):
            return {"error": "impossible"}
        for subset in combinations(jobs, k):
            ids = {job["id"] for job in subset}
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            active_ends = []
            valid = True
            for job in sorted(subset, key=lambda j: (j["start"], j["end"], j["id"])):
                active_ends = [end for end in active_ends if end > job["start"]]
                active_ends.append(job["end"])
                if len(active_ends) > 2:
                    valid = False
                    break
            if not valid:
                continue

            selected = tuple(sorted(ids))
            value = sum(job["value"] for job in subset)
            if (best_value is None or value > best_value
                    or (value == best_value and selected < best_ids)):
                best_value = value
                best_ids = selected

        if best_ids is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _component_08():
    def solve(data):
        required = data.get("required", [])
        bit_for = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        initial_mask = bit_for.get(data["source"], 0)
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)

        start_state = (data["source"], initial_mask, data["coupons"])
        distances = {start_state: data["start"]}
        queue = [(data["start"], data["source"], initial_mask, data["coupons"])]
        while queue:
            time, node, mask, remaining = heapq.heappop(queue)
            state = (node, mask, remaining)
            if distances.get(state) != time:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(depart + edge["duration"], remaining)]
                if remaining:
                    duration = max(2, edge["duration"] - edge.get("discount", 0))
                    options.append((depart + duration, remaining - 1))
                next_mask = mask | bit_for.get(edge["v"], 0)
                for arrival, coupons_left in options:
                    if arrival > data["deadline"]:
                        continue
                    next_state = (edge["v"], next_mask, coupons_left)
                    if arrival < distances.get(next_state, float("inf")):
                        distances[next_state] = arrival
                        heapq.heappush(queue, (arrival, edge["v"], next_mask, coupons_left))
        return {"arrival": None}
    return solve


